func (s RobotServiceServer) apply(ctx context.Context, ref *apptest.RobotRef, doc *patchpb.Patch, by string) (*apptest.Robot, error) {
	plan := &ormpatch.Plan{Entity: robotOrmEntity}
	if doc != nil {
		v, err := ormpatch.Compile(robotOrmEntity, doc)
		if err != nil {
			if errors.Is(err, ormpatch.ErrUnsupported) {
				return nil, status.Errorf(codes.Unimplemented, "%s", err)
			}
			return nil, status.Errorf(codes.InvalidArgument, "%s", err)
		}
		plan = v
	}

	pred, mod, err := entpatch.Build(plan, robotPatchColumns, s.Db.Dialect())
	if err != nil {
		if errors.Is(err, entpatch.ErrValue) {
			return nil, status.Errorf(codes.InvalidArgument, "%s", err)
		}
		return nil, status.Errorf(codes.Internal, "%s", err)
	}

	tx, err := enttx.Join[*ent.Client, *ent.Tx](ctx, s.Db, true)
	if err != nil {
		return nil, err
	}
	defer tx.Close()

	st := s
	st.Db = tx.Db

	k, err := RobotGetKey(ctx, st.Db, ref)
	if err != nil {
		return nil, err
	}
	at := &apptest.RobotRef{}
	at.SetId(k[:])
	p, err := s.narrow(ctx, robot.IDEQ(k))
	if err != nil {
		return nil, err
	}

	if mod == nil {
		q := st.Db.Robot.Query().Where(p)
		if pred != nil {
			q.Where(predicate.Robot(pred))
		}
		if ok, err := q.Exist(ctx); err != nil {
			return nil, err
		} else if !ok {
			return nil, func() error {
				if ok, err := st.Db.Robot.Query().Where(p).Exist(ctx); err != nil {
					return err
				} else if !ok {
					return status.Error(codes.NotFound, "Robot not found")
				}
				return status.Error(codes.FailedPrecondition, "a test in the patch did not hold")
			}()
		}
	} else {
		q := st.Db.Robot.Update().Where(p)
		if pred != nil {
			q.Where(predicate.Robot(pred))
		}
		q.Modify(mod)
		if !plan.WritesTo(13) {
			q.SetDateUpdated(st.now())
		}
		if n, err := q.Save(ctx); err != nil {
			if err, ok := err.(*ent.ConstraintError); ok {
				if sqlgraph.IsUniqueConstraintError(err) {
					return nil, status.Error(codes.AlreadyExists, "Robot already exists")
				}
				if sqlgraph.IsForeignKeyConstraintError(err) {
					return nil, status.Error(codes.NotFound, "Robot: referenced entity not found")
				}
			}
			return nil, err
		} else if n == 0 {
			return nil, func() error {
				if ok, err := st.Db.Robot.Query().Where(p).Exist(ctx); err != nil {
					return err
				} else if !ok {
					return status.Error(codes.NotFound, "Robot not found")
				}
				return status.Error(codes.FailedPrecondition, "a test in the patch did not hold")
			}()
		}
	}

	if mod != nil {
		if err := record(ctx, s.Rec, st.Db, Change{
			By:    by,
			Key:   k,
			Patch: doc,
		}); err != nil {
			return nil, err
		}
	}

	out, err := st.Get(ctx, at.Pick())
	if err != nil {
		return nil, err
	}
	if err := tx.Commit(); err != nil {
		return nil, err
	}
	return out, nil
}

func (s RobotServiceServer) Erase(ctx context.Context, req *apptest.RobotRef) (*apptest.RobotEraseResponse, error) {
	p, err := RobotPick(req)
	if err != nil {
		return nil, err
	}
	p, err = s.narrow(ctx, p)
	if err != nil {
		return nil, err
	}

	tx, err := enttx.Join[*ent.Client, *ent.Tx](ctx, s.Db, s.Rec != nil)
	if err != nil {
		return nil, err
	}
	defer tx.Close()

	st := s
	st.Db = tx.Db

	var k any
	if s.Rec != nil {
		v, err := st.Db.Robot.Query().Where(p).OnlyID(ctx)
		if err != nil {
			if ent.IsNotFound(err) {
				return &apptest.RobotEraseResponse{}, nil
			}
			return nil, err
		}

		k = v
		p = robot.And(p, robot.IDEQ(v))
	}

	u := st.Db.Robot.Update().Where(p)
	u.SetDateErased(st.now())
	u.SetDateUpdated(st.now())
	n, err := u.Save(ctx)
	if err != nil {
		return nil, err
	}
	if n > 0 {
		if err := record(ctx, s.Rec, st.Db, Change{
			By:  apptest.RobotService_Erase_FullMethodName,
			Key: k,
		}); err != nil {
			return nil, err
		}
	}
	if err := tx.Commit(); err != nil {
		return nil, err
	}
	res := &apptest.RobotEraseResponse{}
	res.SetErased(n > 0)

	return res, nil
}

// RobotPick answers with the predicate this reference selects on,
// among the rows that are still here.
//
// Erasure is part of the reference and not only part of a read's scope,
// because a reference to a Robot is composed into the reference of
// whatever names one: an index over an edge asks this for a predicate and
// puts it inside `HasRobotWith`, where no narrowing of a Robot
// is ever applied. A child of an erased row would otherwise be readable by
// naming its parent.
func RobotPick(req *apptest.RobotRef) (predicate.Robot, error) {
	p, err := pickRobot(req)
	if err != nil {
		return nil, err
	}

	return robot.And(robot.DateErasedIsNil(), p), nil
}

func pickRobot(req *apptest.RobotRef) (predicate.Robot, error) {
	switch req.WhichKey() {
	case apptest.RobotRef_Id_case:
		if v, err := uuid.FromBytes(req.GetId()); err != nil {
			return nil, status.Errorf(codes.InvalidArgument, "id: %s", err)
		} else {
			return robot.IDEQ(v), nil
		}
	case apptest.RobotRef_Slug_case:
		k := req.GetSlug()
		ps := make([]predicate.Robot, 0, 2)
		ps = append(ps, robot.AliasEQ(k.GetAlias()))
		if p, err := TenantPick(k.GetTenant()); err != nil {
			return nil, status.Errorf(codes.InvalidArgument, "slug.tenant: %s", err)
		} else {
			ps = append(ps, robot.HasTenantWith(p))
		}
		return robot.And(ps...), nil
	case apptest.RobotRef_Key_not_set_case:
		return nil, status.Errorf(codes.InvalidArgument, "key not set: Robot")
	default:
		return nil, status.Errorf(codes.Unimplemented, "unknown type of key: %s", req.WhichKey())
	}
}

