// JointPick answers with the predicate this reference selects on,
// among the rows that are still here.
//
// Erasure is part of the reference and not only part of a read's scope,
// because a reference to a Joint is composed into the reference of
// whatever names one: an index over an edge asks this for a predicate and
// puts it inside `HasJointWith`, where no narrowing of a Joint
// is ever applied. A child of an erased row would otherwise be readable by
// naming its parent.
func JointPick(req *apptest.JointRef) (predicate.Joint, error) {
	p, err := pickJoint(req)
	if err != nil {
		return nil, err
	}

	return joint.And(joint.DateErasedIsNil(), p), nil
}

func pickJoint(req *apptest.JointRef) (predicate.Joint, error) {
	switch req.WhichKey() {
	case apptest.JointRef_Id_case:
		if v, err := uuid.FromBytes(req.GetId()); err != nil {
			return nil, status.Errorf(codes.InvalidArgument, "id: %s", err)
		} else {
			return joint.IDEQ(v), nil
		}
	case apptest.JointRef_Key_not_set_case:
		return nil, status.Errorf(codes.InvalidArgument, "key not set: Joint")
	default:
		return nil, status.Errorf(codes.Unimplemented, "unknown type of key: %s", req.WhichKey())
	}
}

type FleetServiceServer struct {
	Store

	apptest.UnimplementedFleetServiceServer
}

// NewFleetServiceServer answers with a server that runs its queries with `db`.
//
// It takes the options of [Server] so that what is built here can be told
// where to report its writes and what it may see. Built without them, it
// reports nowhere and sees everything.
func NewFleetServiceServer(db *ent.Client, opts ...Option) apptest.FleetServiceServer {
	s := Server{Store: Store{Db: db}}
	for _, opt := range opts {
		opt(&s)
	}
	return FleetServiceServer{Store: s.Store}
}

// FleetNarrow answers with `p` and everything else that narrows a
// read of a Fleet: the rows that have not been erased, and whatever
// `scope` says of those.
//
// Every read this package makes goes through it, and a read written by
// hand should too -- a List is the one read nothing generates, and so the
// one that would otherwise answer with rows nobody should be given.
func FleetNarrow(ctx context.Context, scope Scope, p predicate.Fleet) (predicate.Fleet, error) {
	ps := make([]predicate.Fleet, 0, 3)

	// A row that was erased is not a row a read answers with.
	ps = append(ps, fleet.DateErasedIsNil())
	if p != nil {
		ps = append(ps, p)
	}
	if scope != nil {
		q, err := scope.FleetScope(ctx)
		if err != nil {
			return nil, err
		}
		if q != nil {
			ps = append(ps, q)
		}
	}

	switch len(ps) {
	case 0:
		return nil, nil
	case 1:
		return ps[0], nil
	default:
		return fleet.And(ps...), nil
	}
}

// narrow is [FleetNarrow] with this server's own scope.
func (s FleetServiceServer) narrow(ctx context.Context, p predicate.Fleet) (predicate.Fleet, error) {
	return FleetNarrow(ctx, s.Scope, p)
}

